const { accessSync, constants } = await import('node:fs');
const pdfPath = process.env.PDF_PATH;
if (!pdfPath) { throw new Error('PDF_PATH env var not set'); }
try { accessSync(pdfPath, constants.R_OK); } catch { throw new Error('PDF file not accessible'); }
globalThis.pdfPath = pdfPath;

const { PDFParse } = await import('pdf-parse');
const { readFileSync } = await import('node:fs');
const buffer = readFileSync(globalThis.pdfPath);
const parser = new PDFParse({ data: buffer });
const result = await parser.getText();
await parser.destroy();
globalThis.rawText = result.text;

const lines = globalThis.rawText.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
if (lines.length === 0) { throw new Error('No text extracted from PDF'); }
globalThis.heading = lines[0];
